from datetime import date, datetime, timedelta, timezone
from decimal import Decimal
import logging
from typing import Any, Optional

from app.services.bank_integration.base import (
    BankProvider,
    BankRenewalStatus,
    BankVerificationStatus,
    ProviderMode,
    RenewalStatusResult,
    VerificationResult,
)

logger = logging.getLogger(__name__)

MOCK_DISCLAIMER = (
    "PROTOTYPE DEMONSTRATION ONLY: Synthetic test data generated by MockBankProvider. "
    "No real banking connectivity or Core Banking System (CBS) integration exists. "
    "This simulation cannot be used as legal, banking, or official regulatory verification."
)


class MockBankProvider(BankProvider):
    """
    Deterministic Mock Bank Provider designed specifically for Smart India Hackathon
    (SIH) demonstrations, evaluation, automated testing, and development.

    All responses are synthetically constructed with explicit disclaimers.
    Never claims to connect to a real banking network.
    """

    @property
    def name(self) -> str:
        return "SIMULATED_MOCK_PROVIDER"

    @property
    def mode(self) -> ProviderMode:
        return ProviderMode.DEMO

    @property
    def disclaimer(self) -> str:
        return MOCK_DISCLAIMER

    def verify_fdr(
        self,
        fdr_number: str,
        institution_reference: str,
        expected_details: Optional[dict[str, Any]] = None,
        simulation_scenario: Optional[str] = None,
    ) -> VerificationResult:
        """
        Synthetically verify an FDR against mock Core Banking System (CBS) records.
        Evaluates field matching deterministically.
        """
        clean_num = str(fdr_number or "").strip().upper()
        clean_inst = str(institution_reference or "").strip()
        scenario = str(simulation_scenario or "").strip().upper()
        expected = expected_details or {}

        # 1. Deterministic simulation override check
        # Timeout / Unavailable scenario
        if scenario in ("SIMULATE_TIMEOUT", "SIMULATE_UNAVAILABLE", "UNAVAILABLE") or any(
            t in clean_num for t in ("TIMEOUT", "UNAVAIL", "GATEWAYERR", "DOWN")
        ):
            return VerificationResult(
                is_mock=True,
                provider_name=self.name,
                provider_mode=self.mode.value,
                status=BankVerificationStatus.UNAVAILABLE.value,
                fdr_number=clean_num,
                bank_reference=None,
                matched_fields={},
                mismatched_fields={},
                bank_fdr_details=None,
                message="Simulated Core Banking gateway timeout after 10,000ms. Participating bank API unavailable.",
                disclaimer=self.disclaimer,
            )

        # Not Found scenario
        if scenario in ("SIMULATE_NOT_FOUND", "NOT_FOUND") or any(
            t in clean_num for t in ("NOTFOUND", "MISSING", "UNKNOWN", "404")
        ):
            return VerificationResult(
                is_mock=True,
                provider_name=self.name,
                provider_mode=self.mode.value,
                status=BankVerificationStatus.NOT_FOUND.value,
                fdr_number=clean_num,
                bank_reference=None,
                matched_fields={},
                mismatched_fields={},
                bank_fdr_details=None,
                message=f"FDR account '{clean_num}' was not found in the simulated bank CBS database for institution '{clean_inst}'.",
                disclaimer=self.disclaimer,
            )

        # Parameter Mismatch scenario
        if scenario in ("SIMULATE_MISMATCH", "MISMATCH") or any(
            t in clean_num for t in ("MISMATCH", "DIFF", "TAMPER", "DISCREPANCY")
        ):
            # Construct synthetic bank parameters with deliberate discrepancies
            expected_amt = Decimal(str(expected.get("amount") or "1000000.00"))
            bank_amt = expected_amt - Decimal("250000.00") if expected_amt > Decimal("300000.00") else expected_amt + Decimal("150000.00")

            expected_mat = expected.get("maturity_date") or expected.get("maturityDate") or (date.today() + timedelta(days=365)).isoformat()
            if isinstance(expected_mat, date):
                expected_mat = expected_mat.isoformat()
            # Mismatch maturity date by 60 days
            bank_mat = (date.fromisoformat(str(expected_mat)[:10]) - timedelta(days=60)).isoformat()

            bank_details = {
                "fdr_number": clean_num,
                "account_title": f"M/S {clean_inst} - AICTE Joint Account",
                "bank_name": expected.get("bank_name") or "State Bank of India",
                "branch_name": "Main Industrial Branch (CBS Branch 0402)",
                "deposit_amount": float(bank_amt),
                "currency": "INR",
                "issue_date": expected.get("issue_date") or (date.today() - timedelta(days=365 * 2)).isoformat(),
                "maturity_date": bank_mat,
                "lien_marked": True,
                "lien_favor": "All India Council for Technical Education (AICTE)",
                "cbs_account_status": "ACTIVE_LIEN_HOLD",
            }

            matched = {
                "fdr_number": clean_num,
                "lien_marked": True,
                "lien_favor": "AICTE",
            }
            mismatched = {
                "amount": {
                    "expected": float(expected_amt),
                    "bank_value": float(bank_amt),
                    "discrepancy_note": "Bank CBS shows lower deposit principal than claimed in portal.",
                },
                "maturity_date": {
                    "expected": str(expected_mat)[:10],
                    "bank_value": bank_mat,
                    "discrepancy_note": "Bank deposit matures earlier than recorded in AICTE portal.",
                },
            }

            return VerificationResult(
                is_mock=True,
                provider_name=self.name,
                provider_mode=self.mode.value,
                status=BankVerificationStatus.MISMATCH.value,
                fdr_number=clean_num,
                bank_reference=f"MOCK-CBS-MIS-{abs(hash(clean_num)) % 1000000:06d}",
                matched_fields=matched,
                mismatched_fields=mismatched,
                bank_fdr_details=bank_details,
                message="Discrepancies identified between institutional submission and simulated bank CBS parameters.",
                disclaimer=self.disclaimer,
            )

        # Standard / Matched scenario
        exp_amount = Decimal(str(expected.get("amount") or "1500000.00"))
        exp_issue = expected.get("issue_date") or (date.today() - timedelta(days=365 * 3)).isoformat()
        exp_mat = expected.get("maturity_date") or expected.get("maturityDate") or (date.today() + timedelta(days=90)).isoformat()

        if isinstance(exp_issue, date):
            exp_issue = exp_issue.isoformat()
        if isinstance(exp_mat, date):
            exp_mat = exp_mat.isoformat()

        bank_details = {
            "fdr_number": clean_num,
            "account_title": f"M/S {clean_inst} - AICTE Joint Account",
            "bank_name": expected.get("bank_name") or expected.get("bankName") or "State Bank of India",
            "branch_name": expected.get("branch_name") or expected.get("branchName") or "University Branch (CBS 0108)",
            "deposit_amount": float(exp_amount),
            "currency": "INR",
            "issue_date": str(exp_issue)[:10],
            "maturity_date": str(exp_mat)[:10],
            "interest_rate": 6.85,
            "lien_marked": True,
            "lien_favor": "All India Council for Technical Education (AICTE)",
            "cbs_account_status": "ACTIVE_LIEN_HOLD",
            "joint_holder": "Member Secretary, AICTE",
        }

        matched = {
            "fdr_number": clean_num,
            "amount": float(exp_amount),
            "maturity_date": str(exp_mat)[:10],
            "bank_name": bank_details["bank_name"],
            "lien_marked": True,
            "lien_favor": "AICTE",
        }

        return VerificationResult(
            is_mock=True,
            provider_name=self.name,
            provider_mode=self.mode.value,
            status=BankVerificationStatus.MATCHED.value,
            fdr_number=clean_num,
            bank_reference=f"MOCK-CBS-REF-{abs(hash(clean_num)) % 1000000:06d}",
            matched_fields=matched,
            mismatched_fields={},
            bank_fdr_details=bank_details,
            message="Simulated verification successful: All FDR parameters, lien status, and joint endorsement match bank CBS.",
            disclaimer=self.disclaimer,
        )

    def get_fdr_details(
        self,
        fdr_number: str,
        institution_reference: str,
    ) -> dict[str, Any]:
        """Query synthetic CBS record for raw FDR details."""
        res = self.verify_fdr(fdr_number, institution_reference)
        return {
            "fdr_number": fdr_number,
            "institution_reference": institution_reference,
            "status": res.status,
            "details": res.bank_fdr_details,
            "is_mock": True,
            "disclaimer": self.disclaimer,
        }

    def get_renewal_status(
        self,
        bank_reference: str,
    ) -> RenewalStatusResult:
        """
        Query status of a simulated renewal transaction.
        """
        clean_ref = str(bank_reference or "").strip().upper()

        if any(t in clean_ref for t in ("TIMEOUT", "UNAVAIL", "DOWN")):
            return RenewalStatusResult(
                is_mock=True,
                provider_name=self.name,
                provider_mode=self.mode.value,
                status=BankRenewalStatus.UNAVAILABLE.value,
                bank_reference=clean_ref,
                message="Simulated CBS branch link timed out.",
                disclaimer=self.disclaimer,
            )

        if any(t in clean_ref for t in ("REJECT", "DECLINE", "FAILED")):
            return RenewalStatusResult(
                is_mock=True,
                provider_name=self.name,
                provider_mode=self.mode.value,
                status=BankRenewalStatus.REJECTED.value,
                bank_reference=clean_ref,
                message="Simulated bank rejection: Institution failed to provide branch renewal mandate with joint signature.",
                disclaimer=self.disclaimer,
            )

        if any(t in clean_ref for t in ("PENDING", "PROCESSING", "QUEUE")):
            return RenewalStatusResult(
                is_mock=True,
                provider_name=self.name,
                provider_mode=self.mode.value,
                status=BankRenewalStatus.PENDING.value,
                bank_reference=clean_ref,
                message="Simulated bank renewal instruction is currently pending branch manager authorization.",
                disclaimer=self.disclaimer,
            )

        if any(t in clean_ref for t in ("NOTFOUND", "UNKNOWN", "404")):
            return RenewalStatusResult(
                is_mock=True,
                provider_name=self.name,
                provider_mode=self.mode.value,
                status=BankRenewalStatus.NOT_FOUND.value,
                bank_reference=clean_ref,
                message="Bank transaction reference not found in simulated CBS clearing ledger.",
                disclaimer=self.disclaimer,
            )

        # Default confirmed renewal
        new_mat = (date.today() + timedelta(days=365 * 3)).isoformat()
        return RenewalStatusResult(
            is_mock=True,
            provider_name=self.name,
            provider_mode=self.mode.value,
            status=BankRenewalStatus.CONFIRMED.value,
            bank_reference=clean_ref or f"MOCK-REN-REF-{abs(hash(str(date.today()))) % 100000:05d}",
            renewal_details={
                "renewal_fdr_number": f"REN-{clean_ref[-6:]}" if len(clean_ref) >= 6 else "REN-998877",
                "new_issue_date": date.today().isoformat(),
                "new_maturity_date": new_mat,
                "renewal_tenure_months": 36,
                "revised_interest_rate": 7.10,
                "lien_continued": True,
            },
            message="Simulated bank renewal confirmed: Deposit term extended by 36 months under joint lien.",
            disclaimer=self.disclaimer,
        )
